const express = require('express');
const { exec } = require('child_process');

class CommandBuilder {
  constructor(cmd) { this.cmd = cmd; this.args = []; }
  _format(value) {
    if (typeof value === 'string') {
      if (value.includes("'")) throw new Error('quote');
      if (['$', ' ', '#', '\\', ';'].some((c) => value.includes(c))) return `'${value}'`;
    }
    return `${value}`;
  }
  arg(...values) { this.args.push(...values.map((v) => this._format(v))); return this; }
  build() { return [this.cmd, ...this.args].join(' '); }
}

const app = express();
app.use(express.json());

app.post('/api/scan', (req, res) => {
  const cmd = new CommandBuilder('scanimage')
    .arg('--device', req.body.params.deviceId)
    .arg('--mode', req.body.params.mode)
    .arg('-b', req.body.params.brightness)
    .build();
  exec(cmd, (err, stdout) => res.json({ stdout, error: err && err.message }));
});

app.listen(8080);

const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve('.');

http.createServer((req, res) => {
  let filePath = req.url.split('?')[0];
  filePath = path.join(ROOT, filePath);
  fs.exists(filePath, (exists) => {
    if (!exists) {
      res.writeHead(404);
      return res.end();
    }
    fs.createReadStream(filePath).pipe(res);
  });
}).listen(8080);

