const express = require('express');
const multer = require('multer');
const AdmZip = require('adm-zip');
const fs = require('fs');
const path = require('path');

const upload = multer({ dest: '/tmp/mcpb' });
const app = express();

app.post('/api/mcpb/upload', upload.single('mcpbFile'), (req, res) => {
  const zip = new AdmZip(req.file.path);
  const manifest = JSON.parse(zip.readAsText('manifest.json'));
  const finalExtractDir = path.join('/srv/data/uploads/mcpb', `server-${manifest.name}`);
  fs.mkdirSync(finalExtractDir, { recursive: true });
  zip.extractAllTo(finalExtractDir, true);
  res.json({ installed: manifest.name });
});

app.listen(3000);

const express = require('express');
const knex = require('knex')({ client: 'sqlite3', connection: { filename: '/tmp/ghost.db' } });

const app = express();

app.get('/ghost/api/admin/members/events', async (req, res) => {
  const filter = req.query.filter || '';
  const match = /data\.post_id:([^,\]]+)/.exec(filter);
  const postId = match ? match[1] : '';
  const rows = await knex.raw(
    `SELECT mce.id, mce.member_id FROM members_click_events mce
     INNER JOIN redirects r ON mce.redirect_id = r.id
     WHERE r.post_id = '${postId}'`
  );
  res.json(rows);
});

app.listen(3000);

import { fetchSafe } from '../utils/fetch.ts';

interface Props {
  url: string;
}

export default async function AnalyticsScript(props: Props): Promise<Response> {
  const url = props.url || 'https://cdn.example.com/analytics.js';
  const original = await fetchSafe(url);
  const response = new Response(original.body, original);
  response.headers.set('Content-Type', 'text/javascript');
